/**
 * Centralized Constants for fullstack-audit-skill
 * Single source of truth for versioning, engine metadata, and harness definitions.
 */
export const FULLSTACK_AUDIT_VERSION = "2.17.1";
export const FULLSTACK_AUDIT_ENGINE = "Living Fullstack Atlas & Precision Adaptive Engine v2.17.1";
export const FULLSTACK_AUDIT_RELEASE_DATE = "2026-11-08";
export function getVersionBanner() {
    return `fullstack-audit v${FULLSTACK_AUDIT_VERSION} (engine: ${FULLSTACK_AUDIT_ENGINE}, released: ${FULLSTACK_AUDIT_RELEASE_DATE})`;
}
export function getAtlasProvenanceHeader(title, subtitle) {
    return `<!-- Generated by fullstack-audit v${FULLSTACK_AUDIT_VERSION} on ${FULLSTACK_AUDIT_RELEASE_DATE} -->
# ${title}

> ${subtitle}
> **Atlas Version**: \`v${FULLSTACK_AUDIT_VERSION}\` | **Engine**: \`${FULLSTACK_AUDIT_ENGINE}\` | **Status**: Verified Clean

`;
}
// Zero-Dependency Sub-Word Tokenizer for Code & Architecture Identifiers
export function tokenizeCodeIdentifier(input) {
    if (!input)
        return [];
    return input
        // Split camelCase & PascalCase
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        // Split acronyms like HTMLParser -> HTML Parser
        .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
        // Split punctuation and path separators
        .replace(/[-_./\\:()[\]{}'"`]/g, " ")
        .toLowerCase()
        .split(/\s+/)
        .filter(t => t.length > 1);
}
// Fullstack Concept & Synonym Map (in-memory concept expansion)
export const FULLSTACK_SYNONYMS = {
    "login": ["signin", "auth", "session", "user"],
    "signin": ["login", "auth", "session"],
    "auth": ["login", "signin", "session", "guard", "middleware", "token"],
    "checkout": ["payment", "stripe", "cart", "order", "purchase", "billing", "subscription"],
    "payment": ["checkout", "stripe", "invoice", "billing"],
    "modal": ["dialog", "drawer", "sheet", "overlay", "popup"],
    "dialog": ["modal", "drawer", "sheet", "overlay"],
    "drawer": ["modal", "sheet", "dock", "overlay"],
    "pill": ["badge", "chip", "tag", "capsule"],
    "badge": ["pill", "chip", "tag", "status"],
    "dot": ["pulse", "status", "indicator", "pip"],
    "pulse": ["dot", "live", "animate-pulse"],
    "table": ["model", "schema", "entity", "database", "prisma", "drizzle"],
    "model": ["table", "schema", "entity", "prisma", "drizzle"],
    "api": ["route", "endpoint", "handler", "action", "server"],
    "action": ["server-action", "mutation", "handler", "api"],
    "button": ["btn", "trigger", "cta"],
};
export function expandSynonyms(tokens) {
    const expanded = new Set(tokens);
    for (const token of tokens) {
        const syns = FULLSTACK_SYNONYMS[token];
        if (syns) {
            for (const s of syns)
                expanded.add(s);
        }
    }
    return Array.from(expanded);
}
